import operator
import re
import sys


def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    DIV0 = "#DIV/0!"
    CYCLE = "#CYCLE!"
    # Deep reference chains recurse through several frames per cell.
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 200000))

    token_re = re.compile(r"\d+|[A-Za-z]+\d*|<>|<=|>=|[-+*/(),:=<>]")
    cmp_ops = {
        "=": operator.eq,
        "<>": operator.ne,
        "<": operator.lt,
        "<=": operator.le,
        ">": operator.gt,
        ">=": operator.ge,
    }

    def is_cell(tok):
        return re.fullmatch(r"[A-Za-z]+\d+", tok) is not None

    def parse(text):
        toks = token_re.findall(text)
        pos = 0

        def peek():
            return toks[pos] if pos < len(toks) else None

        def take():
            nonlocal pos
            tok = toks[pos]
            pos += 1
            return tok

        def expr():
            node = term()
            while peek() in ("+", "-"):
                op = take()
                node = ("bin", op, node, term())
            return node

        def term():
            node = unary()
            while peek() in ("*", "/"):
                op = take()
                node = ("bin", op, node, unary())
            return node

        def unary():
            if peek() == "-":
                take()
                return ("neg", unary())
            return atom()

        def arg():
            if pos + 1 < len(toks) and toks[pos + 1] == ":" and is_cell(toks[pos]):
                a = take()
                take()  # ':'
                b = take()
                return ("range", a.upper(), b.upper())
            return ("expr", expr())

        def atom():
            tok = take()
            if tok == "(":
                node = expr()
                take()  # ')'
                return node
            if tok.isdigit():
                return ("num", int(tok))
            if re.fullmatch(r"[A-Za-z]+", tok):
                name = tok.upper()
                take()  # '('
                if name == "IF":
                    left = expr()
                    op = take()
                    right = expr()
                    take()  # ','
                    then = expr()
                    take()  # ','
                    els = expr()
                    take()  # ')'
                    return ("if", op, left, right, then, els)
                args = [arg()]
                while peek() == ",":
                    take()
                    args.append(arg())
                take()  # ')'
                return (name.lower(), args)
            return ("ref", tok.upper())

        return expr()

    def range_names(a, b):
        c1, c2 = sorted((ord(a[0]), ord(b[0])))
        r1, r2 = sorted((int(a[1:]), int(b[1:])))
        for r in range(r1, r2 + 1):
            for c in range(c1, c2 + 1):
                yield chr(c) + str(r)

    values: dict[str, int | str] = {}
    busy: set[str] = set()

    def cell_value(name):
        if name not in cells:
            return 0
        if name in values:
            return values[name]
        if name in busy:
            return CYCLE
        busy.add(name)
        content = cells[name]
        if content.startswith("="):
            result = ev(parse(content[1:]))
        else:
            result = int(content.strip())
        busy.discard(name)
        values[name] = result
        return result

    def ev(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "ref":
            return cell_value(node[1])
        if kind == "neg":
            v = ev(node[1])
            return v if isinstance(v, str) else -v
        if kind == "bin":
            op = node[1]
            left = ev(node[2])
            if isinstance(left, str):
                return left
            right = ev(node[3])
            if isinstance(right, str):
                return right
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if right == 0:
                return DIV0
            q = abs(left) // abs(right)
            return q if (left < 0) == (right < 0) else -q
        if kind == "if":
            left = ev(node[2])
            if isinstance(left, str):
                return left
            right = ev(node[3])
            if isinstance(right, str):
                return right
            branch = node[4] if cmp_ops[node[1]](left, right) else node[5]
            return ev(branch)

        # SUM, MIN, MAX
        vals = []
        for a in node[1]:
            if a[0] == "range":
                for name in range_names(a[1], a[2]):
                    if name not in cells:
                        continue
                    v = cell_value(name)
                    if isinstance(v, str):
                        return v
                    vals.append(v)
            else:
                v = ev(a[1])
                if isinstance(v, str):
                    return v
                vals.append(v)
        if not vals:
            return 0
        if kind == "sum":
            return sum(vals)
        if kind == "min":
            return min(vals)
        return max(vals)

    return {name: cell_value(name) for name in cells}
